import React, { useMemo, useState } from 'react';
import {
  PaginationState,
  getCoreRowModel,
  useReactTable,
} from '@tanstack/react-table';
import { IUserInfo } from '../../core/Interface/user.interface';
import usePageQuery from '../../core/hooks/usePageQuery';
import { generateString } from '../../core/utils';
import { useGetAllPurchaseListQuery, useGetUserQuery } from '../posApi';
import usePurchaseListColumn from './usePurchaseListColum';
import { IPurchaseList } from '../../core/Interface/purchase.interface';

const usePurchaseList = () => {
  const { page } = usePageQuery();
  const [purchaseId, setPurchaseId] = useState<string>('');
  const [popUpPrchaseId, setPopUpPrchaseId] = useState<string>('');
  const [pagination, setPagination] = React.useState<PaginationState>({
    pageIndex: page,
    pageSize: 10,
  });
  const [searchText, setSearchText] = useState('');

  const { data: companyData } = useGetUserQuery();

  const currencyCode = useMemo(() => {
    if (companyData?.data) {
      const userData = companyData.data as IUserInfo;
      if (userData.company.currencyCode) {
        return userData.company.currencyCode;
      }
    }
    return '';
  }, [companyData]);

  const {
    data: purchaseListData,
    isLoading,
    isFetching,
    error,
  } = useGetAllPurchaseListQuery({
    pageIndex: pagination.pageIndex,
    pageSize: pagination.pageSize,
    searchText,
  });

  const purchaseListMemo = useMemo(() => {
    return purchaseListData?.data as IPurchaseList;
  }, [purchaseListData?.data]);

  const viewPurchaseDetails = (id: string) => {
    if (purchaseId === id) {
      setPurchaseId(id + '_' + generateString(5));
      setSearchText('');
    } else {
      setPurchaseId(id);
    }
  };

  const viewPurchaseDetailsPopUp = (id: string) => {
    if (popUpPrchaseId === id) {
      setPopUpPrchaseId(id + '_' + generateString(5));
    } else {
      setPopUpPrchaseId(id);
    }
  };

  const filteredData = useMemo(() => {
    const text = searchText.toLowerCase().trim();
    return purchaseListMemo?.records.filter((record) => {
      const receiptNo = record.receiptNo.toLowerCase();
      const supplierName = record.supplierNameOrMobile.toLowerCase();
      return supplierName.includes(text) || receiptNo.includes(text);
    });
  }, [purchaseListMemo, searchText]);

  const columns = usePurchaseListColumn({
    viewPurchaseDetails,
    viewPurchaseDetailsPopUp,
    currencyCode: currencyCode,
  });

  const table = useReactTable({
    data: error ? [] : filteredData,
    columns: columns,
    initialState: {
      columnVisibility: {
        id: false,
      },
    },
    pageCount: purchaseListMemo?.totalRecords ?? 0,
    state: {
      pagination,
    },
    onPaginationChange: setPagination,
    getCoreRowModel: getCoreRowModel(),
    manualPagination: true,
  });

  return {
    table,
    isLoading: isFetching || isLoading,
    isInitLoading: isLoading,
    error,
    totalCount: purchaseListMemo?.totalRecords ?? 0,
    purchaseId,
    popUpPrchaseId,
    setSearchText,
    setPopUpPrchaseId,
  };
};

export default usePurchaseList;
