import React, { useEffect, useState, useRef, useMemo } from 'react';
import { Backdrop, Box, CircularProgress, Grid } from '@mui/material';
import usePageQuery from '../../core/hooks/usePageQuery';
import { Table } from '@tanstack/react-table';
import ReactTable from '../../components/Table/ReactTable';
import { appColors } from '../../theme/appColors';
import PosTablePagination from '../../components/Table/PosTablePagination';
import {
  useGetPurchaseDetailsByOrderIdQuery,
  useGetUserQuery,
} from '../posApi';
import { IUserInfo } from '../../core/Interface/user.interface';
import { useReactToPrint } from 'react-to-print';
import usePurchaseList from './usePurchaseList';
import { Receipt } from './components/Receipt';
import SearchField from '../../components/ModelPopup/SearchField';
import AnimatedPage from '../../layouts/AnimatedPage';
import NewReceipt from './components/NewReceipt';
import { IPurchaseReceipt } from '../../core/Interface/purchase.interface';

const PurchaseList = () => {
  const {
    table,
    isLoading,
    totalCount,
    popUpPrchaseId,
    purchaseId,
    setSearchText,
  } = usePurchaseList();
  const { setPage } = usePageQuery();
  const [openAddCategory, setOpenAddCategory] = useState(false);

  const { data: companyData } = useGetUserQuery();

  const currencyCode = useMemo(() => {
    const userData = companyData?.data as IUserInfo | undefined;
    return userData?.company?.currencyCode ?? '';
  }, [companyData]);

  const {
    data: purchaseDetailsData,
    isLoading: purchaseDetailsLoading,
    isFetching,
  } = useGetPurchaseDetailsByOrderIdQuery(purchaseId.split('_')[0], {
    skip: !purchaseId,
  });

  useEffect(() => {
    if (popUpPrchaseId) setOpenAddCategory(true);
  }, [popUpPrchaseId]);

  const handlePaginationChangePage = (
    _event: React.MouseEvent<HTMLButtonElement> | null,
    newPage: number
  ) => {
    table.getState().pagination.pageIndex < newPage
      ? table.nextPage()
      : table.previousPage();
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    table.setPageSize(parseInt(event.target.value, 10));
  };

  const handleSearch = (text: string) => {
    setSearchText(text);
  };

  useEffect(() => {
    if (
      !isLoading &&
      table.getState().pagination.pageIndex !== 0 &&
      table.getRowModel().rows.length === 0
    ) {
      setPage(0);
    }
  }, [isLoading, setPage, table]);

  const componentRef = useRef<HTMLDivElement | null>(null);
  const handlePrint = useReactToPrint({ content: () => componentRef.current });

  useEffect(() => {
    const timer = setTimeout(() => {
      if (purchaseDetailsData?.data && componentRef.current) handlePrint();
    }, 10);
    return () => clearTimeout(timer);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [purchaseDetailsData]);

  return (
    <AnimatedPage>
      <Box data-testid="purchaseList">
        <Grid
          container
          display="flex"
          item
          justifyContent="flex-end"
          key={6}
          sx={{ mt: 1 }}
        >
          <SearchField
            buttonName="Search"
            placeholderName="ReceiptNo Or SupplierName"
            setSearchText={handleSearch}
          />
        </Grid>

        <Backdrop
          open={purchaseDetailsLoading || isFetching}
          sx={{ color: '#fff', zIndex: (theme) => theme.zIndex.drawer + 1 }}
        >
          <CircularProgress color="inherit" />
        </Backdrop>

        <div style={{ display: 'none' }}>
          {purchaseDetailsData?.data && (
            <Receipt
              currencyCode={currencyCode}
              purchaseRes={purchaseDetailsData.data as IPurchaseReceipt}
              ref={componentRef}
            />
          )}
        </div>

        {openAddCategory && (
          <NewReceipt
            handleCloseDialog={() => setOpenAddCategory(false)}
            openModel={openAddCategory}
            purchaseId={popUpPrchaseId}
          />
        )}

        <Box sx={{ py: 1 }} />
        <Box
          sx={{
            pb: 1,
            overflow: 'auto',
            maxWidth: '100%',
            minHeight: '560px',
          }}
        >
          <ReactTable
            isLoading={isLoading}
            {...(table as Table<object>)}
          />
        </Box>

        {table.getTotalSize() !== 0 && (
          <Box sx={{ borderTop: `1px solid ${appColors.greenSmoke[40]}` }}>
            <PosTablePagination
              count={totalCount}
              data-testid="pos-pagination"
              onPageChange={handlePaginationChangePage}
              onRowsPerPageChange={handleChangeRowsPerPage}
              page={table.getState().pagination.pageIndex}
              rowsPerPage={table.getState().pagination.pageSize}
              rowsPerPageOptions={[5, 10, 20]}
            />
          </Box>
        )}
      </Box>
    </AnimatedPage>
  );
};

export default PurchaseList;
